#!/usr/bin/env node

const { alldl } = require("../index.js");
const axios = require("axios");
const path = require("path");
const fs = require("fs");

const HELP = `
📥 rahad-dl — download videos from TikTok, Facebook, Instagram, YouTube, X, Reddit, Moj, Josh & more

Usage:
  rahad-dl <url> [options]
  rahad-dl --batch <url1> <url2> ... [options]
  rahad-dl --batch-file <urls.txt> [options]

Options:
  -o, --output <path>   output file or folder (default: current folder)
  -q, --quality <q>     best | high | medium | low | worst | audio |
                        720p | 1080p | 1440p | 2160p | 4k (or bare 720/1080)   (default: best)
  --mp3                 audio only (.mp3, with ID3 tags)
  --bitrate <n>         audio bitrate in kbps: 128 | 192 | 320 (picks the
                        closest audio stream the source offers)
  --audio-format <fmt>  audio container: mp3 | m4a | opus | wav (falls back
                        to the closest available when not served)
  --thumb               also save the video thumbnail next to the file
  --stdout              pipe the media bytes to stdout instead of saving a
                        file (e.g. rahad-dl "<url>" --stdout | ffmpeg -i - out.mp4)
  --live                record a YouTube Live / Twitch live stream
  --duration <s>        live recording length in seconds (default 60, max 3600)
  --info                show title/source only, no download
  --playlist            download all videos from a YouTube playlist, TikTok profile,
                        or Instagram carousel post
  --batch               download several URLs at once (concurrency 3)
  -f, --batch-file <path>
                        read URLs from a text file (one per line; blank lines and
                        lines starting with # are skipped) and download them all
                        (concurrency 3), with per-URL ✅/❌ summary
  --proxy <url>         HTTP proxy for requests; comma-separated values enable
                        round-robin rotation (e.g. --proxy http://p1:8080,http://p2:8080)
  --subs [lang]         download the video + subtitle (.srt) side by side
                        (default lang: en if present, else first available;
                        subtitle-only download stays available via the API:
                        alldl.subtitles(url, { lang, dest }))
  --resume              resume an interrupted download
  --timeout <ms>        API timeout in ms
  serve                 start self-hosted API + web UI:
                       rahad-dl serve --port 3000 --api-key SECRET --proxy http://host:port
  -h, --help            show this help
  -v, --version         show version

Examples:
  rahad-dl "https://www.tiktok.com/@user/video/123"
  rahad-dl "<url>" -o ./videos -q 720p
  rahad-dl "<url>" --mp3 -o song.mp3
  rahad-dl "<url>" --info
  rahad-dl "<playlist_url>" --playlist -o ./playlist
  rahad-dl "<ig_post_url>" --playlist -o ./carousel   # IG carousel → all items
  rahad-dl "<yt_url>" --subs bn -o ./subs
  rahad-dl --batch "<url1>" "<url2>" -o ./videos --proxy http://p1:8080,http://p2:8080
  rahad-dl --batch-file ./urls.txt -o ./videos       # one URL per line
`;

function parseArgs(argv) {
  const o = { _: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "-o" || a === "--output") o.output = argv[++i];
    else if (a === "-q" || a === "--quality") o.quality = argv[++i];
    else if (a === "--mp3") o.mp3 = true;
    else if (a === "--bitrate") o.bitrate = parseInt(argv[++i], 10);
    else if (a === "--audio-format") o.audioFormat = argv[++i];
    else if (a === "--thumb") o.thumb = true;
    else if (a === "--stdout") o.stdout = true;
    else if (a === "--live") o.live = true;
    else if (a === "--duration") o.duration = parseInt(argv[++i], 10);
    else if (a === "--info") o.info = true;
    else if (a === "--playlist") o.playlist = true;
    else if (a === "--batch") o.batch = true;
    else if (a === "-f" || a === "--batch-file") o.batchFile = argv[++i];
    else if (a === "--subs") {
      o.subs = true;
      if (argv[i + 1] && !argv[i + 1].startsWith("-")) o.subsLang = argv[++i];
    }
    else if (a === "--resume") o.resume = true;
    else if (a === "--port") o.port = argv[++i];
    else if (a === "--api-key") o.apiKey = argv[++i];
    else if (a === "--proxy") o.proxy = argv[++i];
    else if (a === "--timeout") o.timeout = parseInt(argv[++i], 10);
    else if (a === "-h" || a === "--help") o.help = true;
    else if (a === "-v" || a === "--version") o.version = true;
    else if (!a.startsWith("-")) o._.push(a);
    else { console.error(`❌ Unknown option: ${a}\n${HELP}`); process.exit(1); }
  }
  return o;
}

function parseBatchFile(filePath) {
  const abs = path.resolve(filePath);
  if (!fs.existsSync(abs)) throw new Error(`Batch file not found: ${filePath}`);
  const lines = fs.readFileSync(abs, "utf8").split(/\r?\n/);
  return lines
    .map((l) => l.trim())
    .filter((l) => l.length > 0 && !l.startsWith("#"));
}

function downloadOpts(args, proxyOpts) {
  return {
    quality: args.quality || "best",
    audioOnly: !!args.mp3 || !!args.audioFormat || !!args.bitrate,
    audioBitrate: args.bitrate || undefined,
    audioFormat: args.audioFormat || undefined,
    thumbnail: !!args.thumb,
    resume: !!args.resume,
    ...proxyOpts,
  };
}

async function runBatchFlow(urls, args, proxyOpts, dest) {
  console.log(`📦 Batch: ${urls.length} URL(s), concurrency 3`);
  const results = await alldl.batch(urls, {
    concurrency: 3,
    ...proxyOpts,
    onProgress: (done, total, item) =>
      console.log(`  [${done}/${total}] ${item.ok ? "✅" : "❌"} ${item.url.slice(0, 60)}${item.ok ? "" : ` — ${item.error}`}`),
  });
  let ok = 0;
  let failed = 0;
  for (let i = 0; i < results.length; i++) {
    if (!results[i].ok) { failed++; continue; }
    try {
      const f = await alldl.download(results[i].url, dest, downloadOpts(args, proxyOpts));
      console.log(`  💾 ${f.path}`);
      ok++;
    } catch (e) {
      console.log(`  ❌ download fail: ${results[i].url.slice(0, 60)}`);
      failed++;
    }
  }
  return { ok, failed };
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.help) { console.log(HELP); process.exit(0); }
  if (args.version) {
    console.log(require("../package.json").version);
    process.exit(0);
  }
  const url = args._[0];
  if (args._[0] === "serve") {
    const { startServer } = require("./serve.js");
    const port = parseInt(args.port || "3000", 10);
    const proxy = args.proxy || null;
    if (proxy) {
      alldl.setProxy(proxy);
      console.log(`🌍 Proxy: ${String(proxy).replace(/:[^:@/]*@/, ":***@")}`);
    }
    await startServer({ port, apiKey: args.apiKey || null });
    return;
  }
  if (!url && !args.batchFile) { console.error(`❌ Please provide a URL.\n${HELP}`); process.exit(1); }
  if (args.timeout) alldl.setTimeout(args.timeout);

  const proxyInput = (() => {
    if (!args.proxy) return null;
    const list = String(args.proxy).split(",").map((s) => s.trim()).filter(Boolean);
    if (list.length === 0) return null;
    return list.length === 1 ? list[0] : list;
  })();
  const proxyOpts = proxyInput ? { proxy: proxyInput } : {};
  if (proxyInput) {
    console.log(`🌍 Proxy: ${String(args.proxy).replace(/:[^:@/]*@/, ":***@")}`);
  }

  try {
    if (args.info) {
      const r = await alldl(url, proxyOpts);
      console.log(`📌 ${r.data.title}`);
      console.log(`📡 Source: ${r.data.source}`);
      console.log(`🔗 ${r.data.videoUrl}`);
      process.exit(0);
    }
    if (args.batch) {
      const urls = args._;
      const dest = args.output || process.cwd();
      await runBatchFlow(urls, args, proxyOpts, dest);
      process.exit(0);
    }
    if (args.batchFile) {
      const urls = parseBatchFile(args.batchFile);
      if (!urls.length) { console.error("❌ Batch file contains no URLs."); process.exit(1); }
      const dest = args.output || process.cwd();
      const { ok, failed } = await runBatchFlow(urls, args, proxyOpts, dest);
      console.log(`\n📊 ${ok} succeeded, ${failed} failed`);
      process.exit(0);
    }
    if (args.subs) {
      const dest = args.output || process.cwd();
      const wantLang = String(args.subsLang || "en").toLowerCase();
      const f = await alldl.download(url, dest, downloadOpts(args, proxyOpts));
      console.log(`✅ Saved: ${f.path}`);
      try {
        const info = await alldl(url, { subtitles: true, ...proxyOpts });
        const tracks = info.data.subtitles || [];
        const track =
          tracks.find((t) => String(t.lang || "").toLowerCase().startsWith(wantLang)) ||
          tracks.find((t) => String(t.lang || "").toLowerCase().startsWith("en")) ||
          tracks[0];
        if (!track) {
          console.log("⚠️  No subtitles available for this video");
        } else {
          const { data: raw } = await axios.get(track.url, { timeout: 20000 });
          const srtText = alldl.subtitlesToSrt(raw);
          if (!srtText.trim()) throw new Error("subtitle file came back empty");
          const srtPath = f.path.replace(/\.[^.\\/]+$/, "") + `.${track.lang}.srt`;
          fs.writeFileSync(srtPath, srtText, "utf8");
          console.log(`✅ Subtitle saved: ${srtPath} [${track.lang} — ${track.name}]`);
        }
      } catch (e) {
        console.log(`⚠️  Subtitles unavailable: ${e.message}`);
      }
      process.exit(0);
    }
    if (args.playlist) {
      const dest = args.output || process.cwd();
      const pl = await alldl.playlist(url);
      console.log(`📋 ${pl.title} — ${pl.count} videos`);
      const needResolve = [];
      const direct = [];
      pl.videos.forEach((v, i) => (v.mediaUrl ? direct.push(i) : needResolve.push(i)));
      const results = new Array(pl.videos.length);
      if (needResolve.length) {
        const batchRes = await alldl.batch(needResolve.map((i) => pl.videos[i].url), {
          concurrency: 3,
          ...proxyOpts,
          onItem: (item, k) => {
            const i = needResolve[k];
            console.log(`  [${i + 1}/${pl.count}] ${item.success ? "✅" : "❌"} ${pl.videos[i].title?.slice(0, 40)}`);
          },
        });
        needResolve.forEach((vi, k) => { results[vi] = batchRes[k]; });
      }
      for (const i of direct) {
        results[i] = { success: true, url: pl.videos[i].url, mediaUrl: pl.videos[i].mediaUrl };
        console.log(`  [${i + 1}/${pl.count}] ✅ ${pl.videos[i].title?.slice(0, 40)} (direct)`);
      }
      for (let i = 0; i < results.length; i++) {
        if (!results[i] || !results[i].success) continue;
        try {
          const f = results[i].mediaUrl
            ? await alldl._downloadDirect(
                results[i].mediaUrl,
                dest,
                { resume: !!args.resume, ...proxyOpts },
                { title: pl.videos[i].title, source: "Instagram" }
              )
            : await alldl.download(results[i].url, dest, downloadOpts(args, proxyOpts));
          console.log(`  💾 ${f.path}`);
        } catch (e) {
          console.log(`  ❌ download fail: ${pl.videos[i].title?.slice(0, 40)}`);
        }
      }
      process.exit(0);
    }
    if (args.live) {
      const dest = args.output || process.cwd();
      const dur = Math.min(3600, Math.max(1, args.duration || 60));
      const r = await alldl.recordLive(url, {
        duration: dur,
        dest,
        ...proxyOpts,
        onProgress: (p) => {
          process.stdout.write(`\r🔴 REC ${p.elapsed}s / ${dur}s — ${p.segments} segments, ${(p.bytes / 1048576).toFixed(1)} MB   `);
        },
      });
      process.stdout.write("\n");
      console.log(`✅ Saved: ${r.path}`);
      console.log(`📌 ${r.title}  [${r.source}] — ${r.segments} segments, ${r.secondsRecorded}s recorded${r.endedEarly ? " (stream ended early)" : ""}`);
      process.exit(0);
    }
    if (args.stdout) {
      const s = await alldl.stream(url, downloadOpts(args, proxyOpts));
      await new Promise((resolve, reject) => {
        s.on("error", reject);
        process.stdout.on("error", reject);
        s.on("end", resolve);
        s.pipe(process.stdout);
      });
      process.exit(0);
    }
    const dest = args.output || process.cwd();
    const opts = {
      ...downloadOpts(args, proxyOpts),
      onProgress: ({ done, total, percent }) => {
        const mb = (done / 1048576).toFixed(1);
        const pct = percent != null ? ` ${percent}%` : "";
        process.stdout.write(`\r⬇️  ${mb} MB${pct}   `);
      },
    };
    const r = await alldl.download(url, dest, opts);
    process.stdout.write("\n");
    console.log(`✅ Saved: ${r.path}`);
    console.log(`📌 ${r.title}  [${r.source}]`);
    if (r.pickedQuality) console.log(`🎚️ Quality picked: ${r.pickedQuality}${r.pickedVideoOnly ? " (video-only stream, no audio)" : ""}`);
    if (r.pickedAudio) console.log(`🎵 Audio picked: ${r.pickedAudio.format || "unknown"} ${r.pickedAudio.bitrate ? r.pickedAudio.bitrate + "kbps" : ""} → ${r.pickedAudio.savedAs}`);
    if (r.thumbnailPath) console.log(`🖼️ Thumbnail: ${r.thumbnailPath}`);
  } catch (e) {
    process.stdout.write("\n");
    console.error(e.message || String(e));
    process.exit(1);
  }
}

if (require.main === module) {
  main().catch((e) => {
    process.stdout.write("\n");
    console.error(e?.message || String(e));
    process.exit(1);
  });
}

module.exports = { parseArgs, parseBatchFile, HELP };
